<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>Tyres Report</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>


    <div class="row">
      <div class="col-md-6">
            <h5 class="mb-0">TYRES GENERAL REPORT</h5>
      </div>
      <div class="col-md-6">

<div class="btn-group">
            <Multiselect
                v-model="tyres_type"
                :options="storeItems"
                label="name"
                placeholder="Select Type"
                :searchable="true"
                :allow-empty="false"
                :disabled="loading_spinner"
                class="me-2"
                style="min-width: 300px;"
            />
         <button
            class="btn btn-success mb-2 me-2"
           @click="printMaterialConsumption()"
        >
            <i class="bi bi-printer fs-4"></i>
        </button>

        <button
            class="btn btn-primary mb-2"
            data-bs-toggle="modal" 
            data-bs-target="#item-usage-modal"
        >
            <i class="bi bi-plus-square fs-4"></i>
        </button>
</div>
      </div>
    </div>

<div class="modal fade mymodal" id="item-usage-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="tyresListModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="tyresListModalLabel">
    {{ isEditing ? 'EDIT TYRE' : 'REGISTER TYRE' }}
</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="resetForm()"></button>
      </div>
      <form @submit.prevent="registertyresList()">
        <div class="modal-body">
                   <div class="row mb-2">
             <div class="col-md-4">
            <label class="form-label small">Select Type</label> 
    <Multiselect
        v-model="store_item"
        :options="storeItems"
        label="name"
        placeholder="Select Type"
        :searchable="true"
        :allow-empty="false"
    />
</div>

              <div  class="col-md-5" >
                            <label class="form-label">Dimension</label> 
                          <input class="form-control" type="text"  placeholder="Eg. 95 mm × 65 mm"
                           v-model="issued">
                        </div>


                                      <div  class="col-md-5" >
                            <label class="form-label">Tyre Number</label> 
                          <input class="form-control" type="text"  placeholder="Eg. 95 mm × 65 mm"
                           v-model="issued">
                        </div>


   <div class="col-md-3">
                        <label class="form-label small">Direction</label>
                        <multiselect 
                            v-model="direction"
                            :options="['RECEIVED','ISSUED']"
                            placeholder="select Direction"
                            :searchable="true"        
                            :multiple="false"
                            :required="true"
                            :allow-empty="false"
                        ></multiselect>
                    </div>

                           <div  class="col-md-3"  v-if="direction === 'ISSUED'">
                            <label class="form-label">Quantity Used</label> 
                          <input class="form-control" type="number" step="any" placeholder="Enter Quantity Used "
                           v-model="issued"
                           :readonly="!store_item"
                          @input="issued = enforceMax(issued,store_item.balance_quantity)"
                          required
                          :min="0.0"
                           >
                        </div>
                         <div class="col-md-3" v-if="direction === 'RECEIVED'">
                                <label for="quantity"> received</label>
                                <input type="number" v-model="received" class="form-control" placeholder="Enter Received Quantity" step="any" >
                            </div>
                            <div class="col-md-3">
                          <label class="form-label">Date</label>
                          <input type="date" class="form-control" v-model="date">
                        </div>

                          <div class="mb-12">
    <label for="message-text" class="col-form-label">Description</label>
    <textarea class="form-control" id="message-text" placeholder="Enter Description" v-model="description"></textarea>
  </div>

                      </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="resetForm()" id="close_modal">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="loading">
            <span v-if="loading" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            save
          </button>
        </div>
      </form>
    </div>
  </div>
</div>



        <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                 <div v-if="loading_spinner" v-html="tableShimmer()"></div>
                    <div  v-else class="custom-table table3">
                        <v-client-table  
    :data="tyresList" 
    :columns="tyresListColumns" 
    :options="table_option">
                           <template #action="props">
                              <a href="javascript:void(0);" 
  title="Edit Item Usage"
  data-bs-toggle="modal" 
  data-bs-target="#item-usage-modal"
  class="text-primary me-2 position-relative"
  @click="openEditModal(props.row)"
>
  <i class="bi bi-pencil-square fs-4"></i>
</a>
             
    
                           </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
    </div>

</template>
<script setup>
    import { onMounted, ref, inject, computed, watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'Tyres Report' });  
    
    const showMessage = inject('showMessage');
    const register_item_usage = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    // const enforceMax = inject('enforceMax')
    const tableShimmer = inject('tableShimmer');
    const waitIndicator = inject('waitIndicator')
    const loadingSpinner = inject('loadingSpinner'); 
   
    
    const loading_spinner = ref(false);
const tyresListColumns = ref(['sno','type','code','dimension','purchased_rate','status','date','action']);
    const isEditing = ref(false);
    const register_item_usage_id = ref('');
    const direction = ref('')

const today = new Date().toISOString().split('T')[0];
const start_date = ref(today);
const end_date = ref(today);
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 51 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

const formatRate = inject('formatRate')
const tyresList = ref([])
const getTyres = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`tyres?type_id=${tyres_type.value.id || ''}`)
    tyresList.value = response.data.map((item, index) => ({
      ...item,
      sno: index + 1,
      purchased_rate : formatRate(item.rate),
      dimension :item.description
    }))
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    loading_spinner.value = false
  }
}
    

const resetForm = () => {
    register_item_usage.value = false;
    isEditing.value = false;
    register_item_usage_id.value = '';
    store_item.value = '';
    description.value = '';
    received.value = 0;
    issued.value = 0;
    direction.value = '';
    date.value = '';
};


 const openEditModal = async (row) => {
    isEditing.value = true;
    console.log(row);
    register_item_usage_id.value = row;

    if (!storeItems.value.length) {
        await getTyreTypes();
    }

    const matched = storeItems.value.find(si => si.id === row.store_item_id);
    store_item.value = matched || row.store_item || '';

    direction.value = row.direction;
    issued.value = row.issued
    received.value = row.received
    description.value = row.description;
    date.value = row.date;
};


const storeItems = ref([])
const getTyreTypes = async () => {
     loading_spinner.value = true
  try {
    const response = await axiosInstance.get(`tyre-groups`)
    storeItems.value = response.data
      .map((item, index) => ({
        ...item,
        SNo: index + 1,
      }))
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    loading_spinner.value = false
  }
}

const store_item = ref('')
const tyres_type = ref('')
const description = ref('')
const date = ref('')
const received = ref('')
const issued = ref('')
const loading = ref(false)


const registertyresList = async () => {
    loading.value = true;
    const payload = {
        store_item_id: store_item.value.id,
        issued: issued.value,
        received: received.value,
        remark: description.value,
        date: date.value,
        bincard_item_id: register_item_usage_id.value.id,
        issuer_id: JSON.parse(localStorage.getItem("user")).id,
    };


    try {
        if (isEditing.value) {
            await axiosInstance.put(`bin-cards/${register_item_usage_id.value.bin_card_id}`, payload);
            showMessage('Item Usage Updated');
        } else {
            await axiosInstance.post('bin-cards', payload);
            showMessage('Item Registered');
        }
        document.getElementById('close_modal').click();
        getTyres();
        resetForm();
    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        loading.value = false;
    }
};

watch(start_date, () => {
    getTyres();
});


watch(tyres_type, () => {
    getTyres();
});




const printMaterialConsumption = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const itemName = store_item.value?.name || 'All Items';

    const totalQuantity = tyresList.value.length
    const totalCost = tyresList.value.reduce((sum, row) => {
      const val = parseFloat(row.rate) || 0;
      return sum + val;
    }, 0);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Tyres Purchase Report</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 13px; }
  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  .meta { display: flex; justify-content: space-between; margin: 10px 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0px 0; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>

<div class="company-title text-style">
  <i>
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>


<hr style="margin-top:20px">

<div class="title text-style">
TYRES HISTORY  REPORT
</div>

<hr>

<div class="meta text-style">
  <div><b>Item:</b> ${itemName}</div>
  <div><b>Period:</b> ${start_date.value} to ${end_date.value}</div>
</div>

<table>
  <thead>
    <tr>
      <th>No.</th>
      <th>Type</th>
      <th class="text-right">Serial_Number</th>
      <th>Dimension</th>
      <th class="text-right">status</th>
      <th>Acquired_Date</th>
      <th class="text-right">Price</th>
    </tr>
  </thead>
  <tbody>
    ${tyresList.value.map((row, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${row.type || '--'}</td>
      <td class="text-right">${row.code || '--'}</td>
      <td>${row.dimension || '--'}</td>
      <td class="text-right">${row.status || '--'}</td>
      <td>${row.date || '--'}</td>
      <td class="text-right">${formatRate(row.rate) || '--'}</td>
    </tr>
    `).join('')}
    <tr>
      <td colspan="5" class="text-right"><strong>TOTAL:</strong></td>
      <td class="text-right"><strong>QTY : ${totalQuantity}</strong></td>
      <td class="text-right"><strong>${formatRate(totalCost)}</strong></td>
    </tr>
  </tbody>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};

    onMounted(() => {
        getTyres ();
        getTyreTypes();
    });
</script>